// Package rules implements the single standard-library rule logic for secret scanning exceptions,
// finding matching, category intervals, and lifecycle checks under HISS-12.
// Code generated by tools/secrets/generate.go; DO NOT EDIT.

package main

import (
	"fmt"
	"path"
	"path/filepath"
	"strings"
	"time"
)

const (
	// MaxExceptionDays bounds an unextended exception (category A or uncategorized).
	MaxExceptionDays = 90
	// DateLayout is the YYYY-MM-DD date format used for entered and expires fields.
	DateLayout = "2006-01-02"
	// MaxPathBytes bounds the length of a relative file path.
	MaxPathBytes = 256
	// MaxRuleIDBytes bounds the length of a gitleaks rule id.
	MaxRuleIDBytes = 128
	// MaxFingerprintBytes bounds the length of a finding fingerprint.
	MaxFingerprintBytes = 512
	// MaxReasonBytes bounds the length of an exception reason.
	MaxReasonBytes = 1024
	// MaxJudgedFindings bounds findings evaluated in one scan.
	MaxJudgedFindings = 10000
	// MaxJudgedEntries bounds exception entries evaluated in one scan.
	MaxJudgedEntries = 500
)

// Entry represents one HISS-12 secret exception.
type Entry struct {
	Path        string `json:"path"`
	RuleID      string `json:"rule_id"`
	Fingerprint string `json:"fingerprint,omitempty"`
	Reason      string `json:"reason"`
	Expires     string `json:"expires"`
	Category    string `json:"category,omitempty"`
	Entered     string `json:"entered,omitempty"`
}

// Finding represents one secret finding in a gitleaks report.
type Finding struct {
	RuleID      string  `json:"RuleID"`
	Description string  `json:"Description,omitempty"`
	StartLine   int     `json:"StartLine"`
	EndLine     int     `json:"EndLine,omitempty"`
	StartColumn int     `json:"StartColumn,omitempty"`
	EndColumn   int     `json:"EndColumn,omitempty"`
	Match       string  `json:"Match,omitempty"`
	Secret      string  `json:"Secret,omitempty"`
	File        string  `json:"File"`
	SymlinkFile string  `json:"SymlinkFile,omitempty"`
	Commit      string  `json:"Commit"`
	Entropy     float32 `json:"Entropy,omitempty"`
	Author      string  `json:"Author,omitempty"`
	Email       string  `json:"Email,omitempty"`
	Date        string  `json:"Date,omitempty"`
	Message     string  `json:"Message,omitempty"`
	Fingerprint string  `json:"Fingerprint"`
}

// Result holds the classified findings and exception entries from Judge.
type Result struct {
	Allowed    []Finding
	Blocking   []Finding
	Stale      []Entry
	Expired    []Entry
	StaleIdx   []int
	ExpiredIdx []int
}

// Failed reports whether any finding is blocking or any exception is stale or expired.
func (r Result) Failed() bool {
	return len(r.Blocking) > 0 || len(r.Stale) > 0 || len(r.Expired) > 0
}

// CategoryDays returns the allowable duration in days for an exception category.
func CategoryDays(category string) (int, bool) {
	switch category {
	case "A":
		return MaxExceptionDays, true
	case "B":
		return 3, true
	case "C":
		return 10, true
	case "D":
		return 120, true
	default:
		return 0, false
	}
}

// Day returns midnight UTC for the calendar day of t.
func Day(t time.Time) time.Time {
	year, month, day := t.Date()
	return time.Date(year, month, day, 0, 0, 0, 0, time.UTC)
}

// ExpiryProblem reports why expires is invalid on today, or returns "".
func ExpiryProblem(expires string, today time.Time) string {
	date, err := time.Parse(DateLayout, expires)
	if err != nil {
		return fmt.Sprintf("expires %q must be a YYYY-MM-DD date", expires)
	}
	latest := Day(today).AddDate(0, 0, MaxExceptionDays)
	if date.After(latest) {
		return fmt.Sprintf("expires %s is more than %d days after today; the latest date allowed is %s",
			expires, MaxExceptionDays, latest.Format(DateLayout))
	}
	return ""
}

// CategoryExpiryProblem reports why a category/entered/expires combination is invalid, or returns "".
func CategoryExpiryProblem(category, entered, expires string, today time.Time) string {
	if category == "" {
		if entered != "" {
			return "entered requires a category"
		}
		return ExpiryProblem(expires, today)
	}
	return categorizedExpiryProblem(category, entered, expires, today)
}

func categorizedExpiryProblem(category, entered, expires string, today time.Time) string {
	days, valid := CategoryDays(category)
	if !valid {
		return fmt.Sprintf("category %q must be A, B, C or D", category)
	}
	enteredDate, err := time.Parse(DateLayout, entered)
	if err != nil {
		return fmt.Sprintf("entered %q must be a YYYY-MM-DD date when category is set", entered)
	}
	want := enteredDate.AddDate(0, 0, days).Format(DateLayout)
	if category != "A" && expires != want {
		return fmt.Sprintf("category %s requires expires %s (entered %s + %d days)", category, want, entered, days)
	}
	if category == "A" {
		return ExpiryProblem(expires, today)
	}
	if _, err := time.Parse(DateLayout, expires); err != nil {
		return fmt.Sprintf("expires %q must be a YYYY-MM-DD date", expires)
	}
	return ""
}

// ValidPath reports whether path is a clean repository-relative file path.
func ValidPath(value string) bool {
	return value != "" && len(value) <= MaxPathBytes && !strings.ContainsAny(value, "\\\x00\r\n") &&
		!strings.HasPrefix(value, "/") && path.Clean(value) == value && value != "." &&
		value != ".." && !strings.HasPrefix(value, "../")
}

// ValidateHISS12Target validates the path, ruleID, fingerprint, and glob fields of a HISS-12 entry.
func ValidateHISS12Target(p, ruleID, fingerprint, glob string) string {
	if glob != "" {
		return "rule HISS-12 must name one file by path, not a glob"
	}
	if p == "" {
		return "rule HISS-12 must name one file by path"
	}
	if !ValidPath(p) || strings.ContainsAny(p, "*?[]\\") {
		return fmt.Sprintf("path %q must be one clean repository-relative file path of at most %d bytes, without glob characters",
			p, MaxPathBytes)
	}
	return validateRuleAndFingerprint(ruleID, fingerprint)
}

func validateRuleAndFingerprint(ruleID, fingerprint string) string {
	if ruleID == "" {
		return "rule HISS-12 must name one gitleaks rule in tool"
	}
	if len(ruleID) > MaxRuleIDBytes || strings.TrimSpace(ruleID) != ruleID || strings.ContainsAny(ruleID, " \t\r\n") {
		return "rule HISS-12 tool must be one rule id of at most 128 bytes"
	}
	if fingerprint != "" {
		if len(fingerprint) > MaxFingerprintBytes || strings.TrimSpace(fingerprint) != fingerprint || strings.ContainsAny(fingerprint, " \t\r\n") {
			return "rule HISS-12 fingerprint must be at most 512 bytes without whitespace"
		}
	}
	return ""
}

// MatchesFinding reports whether the entry matches a finding's path, ruleID, and fingerprint.
func (e Entry) MatchesFinding(findingPath, ruleID, fingerprint string) bool {
	if e.Path != findingPath {
		return false
	}
	if e.RuleID != ruleID {
		return false
	}
	if e.Fingerprint != "" && e.Fingerprint != fingerprint {
		return false
	}
	return true
}

// Expired reports whether the entry has expired on or before today.
func (e Entry) Expired(today time.Time) bool {
	date, err := time.Parse(DateLayout, e.Expires)
	return err != nil || date.Before(Day(today))
}

// NormalizeFindingPath normalizes a finding's file path relative to repoDir.
func NormalizeFindingPath(filePath, repoDir string) string {
	clean := filepath.ToSlash(filepath.Clean(filePath))
	if filepath.IsAbs(clean) && repoDir != "" {
		if rel, err := filepath.Rel(repoDir, clean); err == nil {
			return filepath.ToSlash(filepath.Clean(rel))
		}
	}
	return strings.TrimPrefix(clean, "./")
}

// Judge classifies findings against exceptions on today.
func Judge(findings []Finding, entries []Entry, dir string, today time.Time) Result {
	result := Result{}
	used := make([]bool, len(entries))
	for fIdx := 0; fIdx < len(findings) && fIdx < MaxJudgedFindings; fIdx++ {
		f := findings[fIdx]
		rel := NormalizeFindingPath(f.File, dir)
		if matchFinding(rel, f.RuleID, f.Fingerprint, entries, today, used) {
			result.Allowed = append(result.Allowed, f)
		} else {
			result.Blocking = append(result.Blocking, f)
		}
	}
	for eIdx := 0; eIdx < len(entries) && eIdx < MaxJudgedEntries; eIdx++ {
		if entries[eIdx].Expired(today) {
			result.Expired = append(result.Expired, entries[eIdx])
			result.ExpiredIdx = append(result.ExpiredIdx, eIdx)
		}
		if !used[eIdx] {
			result.Stale = append(result.Stale, entries[eIdx])
			result.StaleIdx = append(result.StaleIdx, eIdx)
		}
	}
	return result
}

func matchFinding(rel, ruleID, fingerprint string, entries []Entry, today time.Time, used []bool) bool {
	var excused bool
	for i := 0; i < len(entries) && i < MaxJudgedEntries; i++ {
		if entries[i].MatchesFinding(rel, ruleID, fingerprint) {
			used[i] = true
			if !entries[i].Expired(today) {
				excused = true
			}
		}
	}
	return excused
}
